from flask import Flask, request, jsonify
import mysql.connector

app = Flask(__name__)
conn = mysql.connector.connect(user='root', password='password', host='127.0.0.1', database='movies')

@app.route('/get_movies_by_director', methods=['POST'])
def get_movies_by_director():
    director = request.form['director']

    query = "SELECT * FROM movies WHERE director = %s"
    cursor = conn.cursor()
    cursor.execute(query, [director])

    movies = cursor.fetchall()

    if not movies:
        return jsonify({'error': 'No movies found'}), 404

    return jsonify(movies)

if __name__ == '__main__':
    app.run()
